import{_ as n,l as i,o as e,c as o,v as r,p as l,x as t,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"虚拟内存分页","description":"","frontmatter":{"title":"虚拟内存分页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paging-vm.md","filePath":"cs/paging-vm.md","lastUpdated":1789023840000}'),h={name:"cs/paging-vm.md"};function A(m,a,P,_,f,u){const s=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="虚拟内存分页" tabindex="-1">虚拟内存分页 <a class="header-anchor" href="#虚拟内存分页" aria-label="Permalink to &quot;虚拟内存分页&quot;">​</a></h1><div class="epigraph"><p>给每个进程一套连续的虚拟地址，用页表把它映到不一定连续、也不一定都在 DRAM 里的物理页。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/inclusive-exclusive-cache">上一课</a>把 cache 缺失分成三类。Cache 仍用物理或虚拟地址去索引 SRAM，地址空间大小等于程序员看见的 DRAM 窗口时，保护与隔离还没有对象。<a href="/cs/privilege-rings">特权级</a>已经禁止用户直接碰机器状态，但还没有把「用户的指针」和「DRAM 的行」分开。<a href="/cs/locality-principle">局部性原理</a>在页这一级同样适用。本课不重讲 cache 标签。缺口是：程序要用的地址空间可以大于物理内存，且各进程必须看不见别人的物理页。本课只钉页、页表与缺页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若程序直接发出物理地址，链接时就要固定装入位置，进程之间也无法用同一套指针约定。DRAM 不够时，只能整程序换入换出。缺口不是再做一块更大的 cache，而是<strong>固定大小的页：虚拟页号经页表变成物理页号，页内偏移原样通过</strong>。</p><p>缺页：页表项无效或页不在 DRAM，陷入内核，从磁盘取页——粒度是页，不是 cache 行。本课不把磁盘调度写进来。</p><p><span class="marginnote">页是保护与换入的单位；cache 行是延迟隐藏的单位。两者都吃局部性，但缺失代价差几个数量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>虚拟地址切成 VPN 与页内偏移。页表是 VPN 到 PPN 的数组，附带有效、可写、用户可访问等位。<a href="/cs/privilege-rings">特权级</a>下，用户访问若越权，精确异常路径已经准备好。命中则物理地址 = PPN 拼接偏移，再进 cache 与<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>。</p>',9)),(e(),l(d,null,{default:t(()=>[p(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20VA%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20VPN%5B%22VPN%22%5D%0A%20%20VA%20--%3E%20OFF%5B%22%E9%A1%B5%E5%86%85%E5%81%8F%E7%A7%BB%22%5D%0A%20%20VPN%20--%3E%20PT%5B%22%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20PT%20--%3E%20PPN%5B%22PPN%22%5D%0A%20%20PPN%20--%3E%20PA%5B%22%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%0A%20%20OFF%20--%3E%20PA%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>每个进程一份页表（或根指针不同）。内核在特权态改页表；用户只看见虚拟地址。后课 TLB 才会说查页表本身也是访存。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分页让装入地址无关：编译用虚拟 0，内核随便找空物理页。换页让工作集留在 DRAM，其余在磁盘——Denning 工作集在这里成为容量问题的页版。Cache 仍处理字与行；本课不把页表项缓存在数据 cache 里讲完。</p><p>写权限位让<a href="/cs/write-back-allocate">写回与写分配</a>那一套脏数据在页级也有对应：页脏则换出时要写磁盘。本课只承认这一位存在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课用单级页表，不管 64 位空间下表有多大——那是<a href="/cs/multi-level-page-table">多级页表</a>。也不引入 TLB。Cache 用物理标签还是虚拟索引，是实现选择，本课只要求最终比较发生在翻译之后或与翻译一致。</p><p>后课默认：load/store 发出虚拟地址；不在页表或权限失败则缺页异常。翻译延迟必须被下一课藏住。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>虚拟页号经页表变物理页号；偏移不译。</li><li>缺页是页级容量/强制问题，代价远高于 cache 缺失。</li><li>TLB 与多级页表是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em> 虚拟内存。</li></ul>',9))])}const D=n(h,[["render",A]]);export{E as __pageData,D as default};
